import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar
  },
  props: {
    ViewInfo: Object
  },
  data() {
    return {
      selectedFiles: [],
      SnackBarComponent: {}
    };
  },
  // mounted() {
  //     if (this.ViewInfo && Array.isArray(this.ViewInfo.image)) {
  //         this.selectedFiles = this.ViewInfo.image.map((url) => ({
  //             file: url,
  //             preview: url,
  //         }));
  //     }
  // },
  watch: {
    ViewInfo: {
      handler(newValue) {
        if (newValue && Array.isArray(newValue.image)) {
          this.selectedFiles = newValue.image.map(url => ({
            file: null,
            preview: url
          }));
        }
      },
      immediate: true,
      deep: true
    }
  },
  methods: {
    addPhotos() {
      this.$refs.fileInput.click();
    },
    handleFileUpload(event) {
      const files = Array.from(event.target.files);
      if (this.selectedFiles.length + files.length > 10) {
        this.showSnackbar("You can only upload up to 10 photos.", "red");
        return;
      }
      this.selectedFiles = [...this.selectedFiles, ...files.map(file => ({
        file,
        preview: URL.createObjectURL(file)
      }))];
    },
    removePhoto(index) {
      this.selectedFiles.splice(index, 1);
    },
    emit_fourth_step() {
      if (this.selectedFiles.length < 5 || this.selectedFiles.length > 10) {
        this.showSnackbar("Please ensure you have selected between 5 to 10 photos before proceeding.", "red");
        return;
      }
      this.$emit("emitfourthstep", this.selectedFiles);
    },
    back_action() {
      this.$emit("emitthirdstep", 2);
    },
    showSnackbar(message, color) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: color,
        SnackbarText: message,
        timeout: 5000,
        Top: true
      };
    }
  }
};
